<?php
/**
 * Static prerender early-serve map maintenance tests.
 *
 * @package Blockstudio
 */

use Blockstudio\Runtime_Cache;
use Blockstudio\Runtime_Settings;
use Blockstudio\Settings;
use Blockstudio\Static_Prerender_Early_Serve;
use Blockstudio\Static_Prerender_Identity;
use PHPUnit\Framework\TestCase;

/**
 * The early-serve map is shared by every site of an installation, so entries
 * of deleted sites and entries whose directory is gone have to be removed by
 * the engine instead of by tools that rewrite its generated file.
 */
class StaticPrerenderMapMaintenanceTest extends TestCase {

	private const MAP_MARKER = 'Generated by Blockstudio. Static prerender early-serve map; do not edit.';

	private string $root;

	private string $cache;

	protected function setUp(): void {
		$this->root  = trailingslashit( get_temp_dir() ) . 'blockstudio-map-maintenance-' . wp_generate_uuid4();
		$this->cache = $this->root . '/cache';
		wp_mkdir_p( $this->cache );
		file_put_contents( $this->root . '/wp-config.php', "<?php\n" );

		add_filter( 'blockstudio/cache/dir', array( $this, 'filter_cache_root' ) );
		add_filter( 'blockstudio/cache/site_key', array( $this, 'filter_site_key' ) );
		add_filter( 'blockstudio/performance/staticPrerender/enabled', '__return_true' );
		add_filter( 'blockstudio/performance/staticPrerender/earlyServe', '__return_true' );
		Settings::reset();
		Runtime_Settings::reset();
		Static_Prerender_Identity::reset();
		Static_Prerender_Early_Serve::override_content_dir_for_testing( $this->root );
		Static_Prerender_Early_Serve::override_config_path_for_testing( $this->root . '/wp-config.php' );
	}

	protected function tearDown(): void {
		remove_filter( 'blockstudio/cache/dir', array( $this, 'filter_cache_root' ) );
		remove_filter( 'blockstudio/cache/site_key', array( $this, 'filter_site_key' ) );
		remove_filter( 'blockstudio/performance/staticPrerender/enabled', '__return_true' );
		remove_filter( 'blockstudio/performance/staticPrerender/earlyServe', '__return_true' );
		Settings::reset();
		Runtime_Settings::reset();
		Static_Prerender_Identity::reset();
		Static_Prerender_Early_Serve::override_content_dir_for_testing( null );
		Static_Prerender_Early_Serve::override_config_path_for_testing( null );
		$this->remove_directory( $this->root );
	}

	public function filter_cache_root(): string {
		return $this->root . '/runtime-cache';
	}

	public function filter_site_key(): string {
		return 'unit-map-maintenance';
	}

	public function test_deleting_a_site_removes_its_entries_and_keeps_the_others(): void {
		$site = $this->site();
		$this->assertTrue( Static_Prerender_Early_Serve::install_artifact_entry( $this->entry( $site['host'], get_current_blog_id(), '1' ), $this->cache ) );
		$this->assertTrue( Static_Prerender_Early_Serve::install_artifact_entry( $this->entry( 'deleted.example', 77, '2' ), $this->cache ) );
		$this->assertTrue( Static_Prerender_Early_Serve::install_artifact_entry( $this->entry( 'unnumbered.example', 0, '3' ), $this->cache ) );

		do_action( 'wp_delete_site', $this->wp_site( 77, 'deleted.example' ) );
		do_action( 'wp_delete_site', $this->wp_site( 78, 'unnumbered.example' ) );

		$this->assertSame( array( $site['key'] ), array_keys( Static_Prerender_Early_Serve::installed_map_entries() ) );
		$this->assertFileExists( Static_Prerender_Early_Serve::dropin_path() );
	}

	public function test_the_map_report_lists_orphaned_and_dead_entries(): void {
		$site     = $this->site();
		$live_dir = $this->root . '/live';
		wp_mkdir_p( $live_dir );
		file_put_contents( $live_dir . '/' . str_repeat( 'a', 64 ) . '.html', '<html>Live</html>' );

		$this->write_map(
			array(
				$site['key']               => $this->raw_entry( $site['host'], get_current_blog_id(), $live_dir, array( '/' => str_repeat( 'a', 64 ), '/gone/' => str_repeat( 'b', 64 ) ) ),
				'deleted.example|/'        => $this->raw_entry( 'deleted.example', 77, $live_dir, array( '/' => str_repeat( 'a', 64 ) ) ),
				'unnumbered.example|/'     => $this->raw_entry( 'unnumbered.example', 0, $live_dir, array( '/' => str_repeat( 'a', 64 ) ) ),
				$this->other_key( $site )  => $this->raw_entry( 'collected.example', get_current_blog_id(), $this->root . '/collected', array( '/' => str_repeat( 'c', 64 ) ) ),
			)
		);

		$this->assertSame(
			array(
				'owned'    => true,
				'entries'  => 4,
				'routes'   => 2,
				'missing'  => 1,
				'dead'     => array( $this->other_key( $site ) ),
				'orphaned' => array( 'deleted.example|/', 'unnumbered.example|/' ),
			),
			$this->sorted_report( Static_Prerender_Early_Serve::map_report() )
		);
	}

	public function test_pruning_removes_orphaned_and_dead_entries_unless_it_is_a_dry_run(): void {
		$site     = $this->site();
		$live_dir = $this->root . '/live';
		wp_mkdir_p( $live_dir );
		file_put_contents( $live_dir . '/' . str_repeat( 'a', 64 ) . '.html', '<html>Live</html>' );
		$entries = array(
			$site['key']              => $this->raw_entry( $site['host'], get_current_blog_id(), $live_dir, array( '/' => str_repeat( 'a', 64 ) ) ),
			'deleted.example|/'       => $this->raw_entry( 'deleted.example', 77, $live_dir, array( '/' => str_repeat( 'a', 64 ) ) ),
			$this->other_key( $site ) => $this->raw_entry( 'collected.example', get_current_blog_id(), $this->root . '/collected', array( '/' => str_repeat( 'c', 64 ) ) ),
		);
		$this->write_map( $entries );
		$before = (string) file_get_contents( Static_Prerender_Early_Serve::map_path() );

		$dry = Static_Prerender_Early_Serve::prune_map( true );

		$this->assertSame(
			array(
				'owned'   => true,
				'kept'    => 1,
				'dropped' => array(
					'deleted.example|/'       => 'orphaned',
					$this->other_key( $site ) => 'dead',
				),
				'written' => false,
			),
			$dry
		);
		$this->assertSame( $before, file_get_contents( Static_Prerender_Early_Serve::map_path() ) );

		$pruned = Static_Prerender_Early_Serve::prune_map();

		$this->assertTrue( $pruned['written'] );
		$this->assertSame( array( $site['key'] ), array_keys( Static_Prerender_Early_Serve::installed_map_entries() ) );
		$this->assertSame( $entries[ $site['key'] ], Static_Prerender_Early_Serve::installed_map_entries()[ $site['key'] ] );
		$this->assertSame( array(), Static_Prerender_Early_Serve::prune_map()['dropped'] );
	}

	public function test_pruning_the_last_entry_removes_the_map_dropin_and_wp_cache_declaration(): void {
		$this->assertTrue( Static_Prerender_Early_Serve::install_artifact_entry( $this->entry( 'deleted.example', 77, '4' ), $this->cache ) );
		$this->assertFileExists( Static_Prerender_Early_Serve::dropin_path() );
		$this->assertStringContainsString( 'WP_CACHE', (string) file_get_contents( $this->root . '/wp-config.php' ) );

		$outcome = Static_Prerender_Early_Serve::prune_map();

		$this->assertSame( array( 'deleted.example|/' => 'orphaned' ), $outcome['dropped'] );
		$this->assertTrue( $outcome['written'] );
		$this->assertFileDoesNotExist( Static_Prerender_Early_Serve::map_path() );
		$this->assertFileDoesNotExist( Static_Prerender_Early_Serve::dropin_path() );
		$this->assertSame( "<?php\n", file_get_contents( $this->root . '/wp-config.php' ) );
	}

	public function test_a_foreign_map_is_neither_reported_nor_pruned(): void {
		$foreign = "<?php\nreturn array( 'entries' => array() );\n";
		file_put_contents( Static_Prerender_Early_Serve::map_path(), $foreign );

		$this->assertFalse( Static_Prerender_Early_Serve::map_report()['owned'] );
		$this->assertFalse( Static_Prerender_Early_Serve::prune_map()['owned'] );
		$this->assertSame( $foreign, file_get_contents( Static_Prerender_Early_Serve::map_path() ) );
	}

	// An identity rotation, such as a core update, retires the namespace an
	// activated artifact was built in. Collecting it left the map pointing at
	// a directory that no longer existed until the next deploy.
	public function test_namespace_collection_keeps_a_namespace_the_map_serves_from(): void {
		$site      = $this->site();
		$namespace = $this->root . '/runtime-cache/sites/unit-map-maintenance/rotated-namespace';
		$artifact  = $namespace . '/static-prerender-artifact';
		$document  = $artifact . '/' . str_repeat( 'd', 64 ) . '.html';
		wp_mkdir_p( $artifact );
		file_put_contents( $document, '<html>Activated</html>' );
		touch( $namespace . '/.retired', time() - 30 * DAY_IN_SECONDS );
		foreach ( array( $document, $artifact ) as $path ) {
			touch( $path, time() - 30 * DAY_IN_SECONDS );
		}
		$this->write_map(
			array(
				$site['key'] => $this->raw_entry( $site['host'], get_current_blog_id(), $artifact, array( '/' => str_repeat( 'd', 64 ) ) ),
			)
		);

		$this->sweep();

		$this->assertFileExists( $document );
		$this->assertFileDoesNotExist( $namespace . '/.retired' );

		$this->write_map( array() );
		$this->sweep();
		$this->assertFileExists( $namespace . '/.retired' );

		touch( $namespace . '/.retired', time() - 2 * DAY_IN_SECONDS );
		$this->sweep();
		$this->assertDirectoryDoesNotExist( $namespace );
	}

	/**
	 * @return array{host:string,home_path:string,key:string}
	 */
	private function site(): array {
		$site = Static_Prerender_Early_Serve::current_site_identity();
		$this->assertIsArray( $site );
		$this->assertSame( '/', $site['home_path'] );

		return $site;
	}

	/**
	 * @param array{host:string,home_path:string,key:string} $site Current site.
	 */
	private function other_key( array $site ): string {
		return 'collected.example|' . $site['home_path'];
	}

	/**
	 * @return array<string,mixed> Artifact entry for install_artifact_entry().
	 */
	private function entry( string $host, int $site_id, string $digit ): array {
		$key = str_repeat( $digit, 64 );
		file_put_contents( $this->cache . '/' . $key . '.html', '<html>' . $host . '</html>' );

		return array(
			'host'            => $host,
			'home_path'       => '/',
			'site_id'         => $site_id,
			'mode'            => 'graph',
			'build_id'        => str_repeat( $digit, 32 ),
			'signature'       => str_repeat( 'c', 32 ),
			'ttl'             => 3600,
			'serve_logged_in' => false,
			'dynamic'         => array(),
			'routes'          => array( '/' => $key ),
		);
	}

	/**
	 * @param array<string,string> $routes Routes.
	 *
	 * @return array<string,mixed> Map entry as the map stores it.
	 */
	private function raw_entry( string $host, int $site_id, string $directory, array $routes ): array {
		return array(
			'host'            => $host,
			'home_path'       => '/',
			'site_id'         => $site_id,
			'dir'             => wp_normalize_path( $directory ),
			'mode'            => 'graph',
			'build_id'        => str_repeat( 'e', 32 ),
			'identity'        => str_repeat( 'e', 32 ),
			'runtime_dir'     => wp_normalize_path( $directory ),
			'signature'       => str_repeat( 'c', 32 ),
			'ttl'             => 3600,
			'serve_logged_in' => false,
			'dynamic'         => array(),
			'routes'          => $routes,
		);
	}

	/**
	 * @param array<string,array<string,mixed>> $entries Entries.
	 */
	private function write_map( array $entries ): void {
		file_put_contents(
			Static_Prerender_Early_Serve::map_path(),
			"<?php\n// " . self::MAP_MARKER . "\nreturn " . var_export( array( 'entries' => $entries ), true ) . ";\n"
		);
	}

	private function wp_site( int $id, string $domain ): WP_Site {
		if ( ! class_exists( 'WP_Site', false ) ) {
			require_once ABSPATH . WPINC . '/class-wp-site.php';
		}

		return new WP_Site(
			(object) array(
				'blog_id' => $id,
				'domain'  => $domain,
				'path'    => '/',
			)
		);
	}

	/**
	 * @param array<string,mixed> $report Map report.
	 *
	 * @return array<string,mixed> Report with sorted key lists.
	 */
	private function sorted_report( array $report ): array {
		foreach ( array( 'dead', 'orphaned' ) as $list ) {
			sort( $report[ $list ] );
		}

		return $report;
	}

	private function sweep(): void {
		wp_mkdir_p( Runtime_Cache::directory( 'runtime' ) );
		@unlink( $this->root . '/runtime-cache/sites/unit-map-maintenance/.namespaces-collected' );
		clearstatcache();
		Runtime_Cache::cleanup_legacy_build_locks_batch();
		clearstatcache();
	}

	private function remove_directory( string $directory ): void {
		if ( ! is_dir( $directory ) ) {
			return;
		}

		$items = new RecursiveIteratorIterator(
			new RecursiveDirectoryIterator( $directory, FilesystemIterator::SKIP_DOTS ),
			RecursiveIteratorIterator::CHILD_FIRST
		);
		foreach ( $items as $item ) {
			if ( $item->isDir() ) {
				rmdir( $item->getPathname() );
			} else {
				unlink( $item->getPathname() );
			}
		}
		rmdir( $directory );
	}
}
